files..promptscript/project.prs:
@meta {
  id: "acme-support"
  syntax: "1.6.0"
  owner: "team-support"
  risk: "medium"
}


@prompts {
  literals: {
    description: "Render literals"
    system: "Home is ${HOME} and ${USER:-nobody}."
    user: "Amount {{input.amount}}, urgent {{input.urgent}}, ratio {{input.ratio}}, big {{input.big}}, tone {{input.tone}}"
    inputs: {
      amount: { type: "number", description: "Amount" }
      urgent: { type: "boolean", description: "Urgent" }
      ratio: { type: "number", description: "Ratio", default: 0.2 }
      big: { type: "number", description: "A large number", default: 1000000000000000000000 }
      tone: { type: "enum", description: "Tone", options: ["warm", "formal"], default: "warm" }
    }
  }
}
